package cn.finance.review;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.security.core.Authentication;
import static cn.finance.review.Db.*;
import static cn.finance.review.ApiError.require;
@Service
public class ReviewService {
 final Db db;final Access access;final PublicationService publications;final QueryService queries;
 public ReviewService(Db db,Access access,PublicationService publications,QueryService queries){this.db=db;this.access=access;this.publications=publications;this.queries=queries;}
 public Map<String,Object> findDraftRecord(Authentication a,String draftId,String originalId,String chain,boolean source){var draft=publications.draft(a,draftId,false);publications.editable(draft);String ds=str(draft,chain+"DatasetId");require(!ds.isBlank(),422,"CHAIN","草稿不包含该链路");if(source){var original=db.one("SELECT s.* FROM "+Fields.sourceTable(chain)+" s JOIN review_dataset d ON s.dataset_id=d.id WHERE s.id=:id AND d.product_id=:p",map("id",originalId,"p",draft.get("productId")));String base=str(original,"baseRowId").isBlank()?originalId:str(original,"baseRowId");var row=db.one("SELECT * FROM "+Fields.sourceTable(chain)+" WHERE dataset_id=:d AND (base_row_id=:base OR id=:id)",map("d",ds,"base",base,"id",originalId));return map("draft",draft,"source",row);}
  var original=db.one("SELECT f.* FROM risk_finding f JOIN review_dataset d ON f.dataset_id=d.id WHERE f.id=:id AND d.product_id=:p",map("id",originalId,"p",draft.get("productId")));String base=str(original,"baseFindingId").isBlank()?originalId:str(original,"baseFindingId");var row=db.one("SELECT f.*,d.* FROM risk_finding f JOIN "+Fields.detailTable(chain)+" d ON f.id=d.finding_id WHERE f.dataset_id=:d AND (f.base_finding_id=:base OR f.id=:id)",map("d",ds,"base",base,"id",originalId));return map("draft",draft,"finding",row,"source",queries.source(chain,str(row,"currentSourceId")));
 }
 public Map<String,Object> editSource(Authentication a,String draftId,String sourceId,String chain,String match,Map<String,Object> body){require(List.of("user","matrix").contains(chain),422,"CHAIN","链路无效");return db.transaction(()->{var d=publications.draft(a,draftId,true);publications.editable(d);String ds=str(d,chain+"DatasetId");var before=db.one("SELECT * FROM "+Fields.sourceTable(chain)+" WHERE id=:id AND dataset_id=:d",map("id",sourceId,"d",ds));require(num(before,"recordVersion")==PublicationService.version(match),412,"RECORD_CHANGED","记录已被修改，请重新读取");String reason=str(body,"reason").trim();require(!reason.isBlank()&&reason.length()<=2000,422,"REASON","请填写修改依据");require(body.get("changes") instanceof Map<?,?>,422,"CHANGES","修改内容无效");Map<?,?> changes=(Map<?,?>)body.get("changes");require(!changes.isEmpty(),422,"CHANGES","修改内容不能为空");String business=chain.equals("matrix")?"permissionCombinationId":"authorizationId";if(changes.containsKey(business)&&!str(before,business).isBlank())require(str(before,business).equals(String.valueOf(changes.get(business)).trim()),409,"BUSINESS_ID_IMMUTABLE","业务标识不可修改，请通过重新导入创建新的业务记录");var after=new LinkedHashMap<>(before);for(var e:changes.entrySet()){String key=String.valueOf(e.getKey());require(Fields.sourceColumns(chain).contains(key),422,"FIELD","字段不可修改");after.put(key,e.getValue()==null?"":String.valueOf(e.getValue()).trim());}
  Map<String,String> named=new LinkedHashMap<>();for(String k:Fields.sourceColumns(chain))if(after.get(k)!=null)named.put(k,String.valueOf(after.get(k)));var normalized=Fields.normalize(named,chain.equals("user")?"AUTH":"POINT");var errors=Fields.validate(normalized,chain.equals("user")?"AUTH":"POINT");require(errors.isEmpty(),422,"VALIDATION",String.join("；",errors));after.putAll(normalized);String recordKey=Fields.storageKey(after,chain,sourceId);require(!Fields.requiresSourceUniqueness(after,chain)||db.count("SELECT COUNT(*) FROM "+Fields.sourceTable(chain)+" WHERE dataset_id=:d AND record_key=:k AND id<>:id",map("d",ds,"k",recordKey,"id",sourceId))==0,422,"DUPLICATE","修改后的业务标识与其他记录重复");var params=Fields.select(after,Fields.sourceColumns(chain));params.put("key",recordKey);params.put("id",sourceId);params.put("v",PublicationService.version(match));String set=String.join(",",Fields.sourceColumns(chain).stream().map(k->snake(k)+"=:"+k).toList());if(chain.equals("user")){set+=",user_key=:userKey";params.put("userKey",Fields.identity(after));}int updated=db.update("UPDATE "+Fields.sourceTable(chain)+" SET "+set+",record_key=:key,record_version=record_version+1 WHERE id=:id AND record_version=:v",params);require(updated==1,412,"RECORD_CHANGED","记录已变化");long affected=db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id=:d AND current_source_id=:id",map("d",ds,"id",sourceId));db.update("UPDATE risk_finding SET workflow='待复核',record_version=record_version+1 WHERE dataset_id=:d AND current_source_id=:id",map("d",ds,"id",sourceId));db.update("UPDATE review_draft SET revision=revision+1 WHERE id=:id",Map.of("id",draftId));db.event(str(d,"productId"),access.actor(a),"EDIT_SOURCE",sourceId,before,after,reason);return map("affected",affected,"recordVersion",num(before,"recordVersion")+1,"draftRevision",num(d,"revision")+1);});}
 public Map<String,Object> editFinding(Authentication a,String draftId,String findingId,String match,Map<String,Object> body){return db.transaction(()->{var d=publications.draft(a,draftId,true);publications.editable(d);var before=db.one("SELECT * FROM risk_finding WHERE id=:id AND dataset_id IN (:ids)",map("id",findingId,"ids",List.of(str(d,"userDatasetId"),str(d,"matrixDatasetId"))));require(num(before,"recordVersion")==PublicationService.version(match),412,"RECORD_CHANGED","风险记录已变化");String reason=str(body,"reason").trim();require(!reason.isBlank()&&reason.length()<=2000,422,"REASON","请填写修正依据");require(body.get("changes") instanceof Map<?,?>,422,"CHANGES","修改内容无效");Map<?,?> changes=(Map<?,?>)body.get("changes");require(!changes.isEmpty(),422,"CHANGES","修改内容不能为空");var after=new LinkedHashMap<>(before);List<String> editable=List.of("risk","workflow","violation","advice","evidence","confidence");for(var e:changes.entrySet()){String key=String.valueOf(e.getKey());require(editable.contains(key),422,"FIELD","此字段不能通过报告纠错修改");after.put(key,e.getValue());}var errors=Fields.validate(after,str(before,"chain").equals("user")?"USER_RISK":"MATRIX_RISK");errors=errors.stream().filter(e->!e.contains("不能为空")).toList();require(errors.isEmpty(),422,"VALIDATION",String.join("；",errors));if(after.get("confidence")!=null)require(QueryService.parseNumber(after.get("confidence"))>=0&&QueryService.parseNumber(after.get("confidence"))<=1,422,"CONFIDENCE","置信度应为0至1");var params=Fields.select(after,editable);params.put("id",findingId);db.update("UPDATE risk_finding SET "+String.join(",",editable.stream().map(k->snake(k)+"=:"+k).toList())+",record_version=record_version+1 WHERE id=:id",params);db.update("UPDATE review_draft SET revision=revision+1 WHERE id=:id",Map.of("id",draftId));db.event(str(d,"productId"),access.actor(a),"CORRECT_FINDING",findingId,before,after,reason);return map("recordVersion",num(before,"recordVersion")+1,"draftRevision",num(d,"revision")+1);});}
}
